    def bands(length, occupied):
        result = []
        i = 0
        while i < length:
            if not occupied(i):
                i += 1
                continue
            start = i
            while i < length and occupied(i):
                i += 1
            result.append((start, i - 1))
        return result

    row_bands = bands(h, lambda r: any(grid[r][c] != 0 for c in range(w)))
    col_bands = bands(w, lambda c: any(grid[r][c] != 0 for r in range(h)))

    counts = {}
    for row in grid:
