def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Find each separated nonzero tile.
    seen = set()
    tiles = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and
                            grid[ny][nx] != 0 and (ny, nx) not in seen):
                        seen.add((ny, nx))
                        stack.append((ny, nx))

            r0 = min(y for y, x in cells)
            r1 = max(y for y, x in cells)
            c0 = min(x for y, x in cells)
            c1 = max(x for y, x in cells)
            interior = {}
            for y, x in cells:
                if r0 < y < r1 and c0 < x < c1:
                    interior[(y - r0, x - c0)] = grid[y][x]
            tiles.append({
                "r0": r0, "r1": r1, "c0": c0, "c1": c1,
                "interior": interior
            })

    # The most common interior color is the ordinary tile fill, not a connector.
    counts = {}
    for tile in tiles:
        for color in tile["interior"].values():
            counts[color] = counts.get(color, 0) + 1
    if not counts:
        return out
    ordinary = max(counts, key=counts.get)

    # Join matching exceptional interior cells across gaps in each tile row.
    row_groups = {}
    for i, tile in enumerate(tiles):
        row_groups.setdefault((tile["r0"], tile["r1"]), []).append(i)

    for indices in row_groups.values():
        keys = set()
        for i in indices:
            for offset, color in tiles[i]["interior"].items():
                if color != ordinary:
                    keys.add((offset[0], offset[1], color))
        for dr, dc, color in keys:
            matching = [
                i for i in indices
                if tiles[i]["interior"].get((dr, dc)) == color
            ]
            matching.sort(key=lambda i: tiles[i]["c0"])
            for a, b in zip(matching, matching[1:]):
                row = tiles[a]["r0"] + dr
                for col in range(tiles[a]["c1"] + 1, tiles[b]["c0"]):
                    if out[row][col] == 0:
                        out[row][col] = color

    # Join matching exceptional interior cells across gaps in each tile column.
    col_groups = {}
    for i, tile in enumerate(tiles):
        col_groups.setdefault((tile["c0"], tile["c1"]), []).append(i)

    for indices in col_groups.values():
        keys = set()
        for i in indices:
            for offset, color in tiles[i]["interior"].items():
                if color != ordinary:
                    keys.add((offset[0], offset[1], color))
        for dr, dc, color in keys:
            matching = [
                i for i in indices
                if tiles[i]["interior"].get((dr, dc)) == color
            ]
            matching.sort(key=lambda i: tiles[i]["r0"])
            for a, b in zip(matching, matching[1:]):
                col = tiles[a]["c0"] + dc
                for row in range(tiles[a]["r1"] + 1, tiles[b]["r0"]):
                    if out[row][col] == 0:
                        out[row][col] = color

    return out
